  F["effusion-size"] = function (i) { var v = i.dias; return { v: r(v, 0), g: grade(v < 10 ? "Small" : v <= 20 ? "Moderate" : "Large", v < 10 ? "ok" : v <= 20 ? "warn" : "bad", "End diastolic depth: under 10 small, 10 to 20 moderate, over 20 mm large. Tamponade is a clinical and Doppler diagnosis.") }; };
  F["mitral-respiratory"] = function (i) { var v = (i.expE - i.inspE) / i.expE * 100; return { v: r(v, 0), g: grade(v >= 25 ? "Meets 25 percent variation" : "Below 25 percent", v >= 25 ? "warn" : "ok", "Inspiratory mitral E fall 25 percent or more supports constriction in the Mayo scheme, tamponade by context.") }; };
  F["tricuspid-respiratory"] = function (i) { var v = (i.inspE - i.expE) / i.expE * 100; return { v: r(v, 0), g: grade(v >= 40 ? "Meets 40 percent variation" : "Below 40 percent", v >= 40 ? "warn" : "ok", "Inspiratory tricuspid E rise 40 percent or more supports constriction or tamponade physiology by context.") }; };
  F["lvot-respiratory"] = function (i) { var v = (i.expV - i.inspV) / i.expV * 100; return { v: r(v, 0), g: grade(v >= 10 ? "Exaggerated variation: correlate for tamponade" : "Normal variation range", v >= 10 ? "warn" : "ok", "A clear inspiratory fall in LVOT VTI mirrors pulsus paradoxus. Ventilation reverses the pattern.") }; };
  F["doppler-equation"] = function (i) { var v = 2 * i.f0 * 1e6 * i.v * Math.cos(i.theta * Math.PI / 180) / i.c / 1000; return { v: r(v, 1), g: grade(i.theta <= 20 ? "Angle acceptable (20 degrees or less)" : i.theta <= 30 ? "Angle error growing" : "Angle too large: velocity understated", i.theta <= 20 ? "ok" : "warn", "Cos 20 degrees is 0.94; cos 60 is 0.50, halving the shift.") }; };
  F["bernoulli"] = function (i) { var simp = 4 * i.v2 * i.v2; var ext = 4 * (i.v2 * i.v2 - i.v1 * i.v1); return { v: r(simp, 0), extra: "Extended gradient " + r(ext, 0) + " mmHg", g: grade(i.v1 >= 1.5 ? "Use the extended form" : "Simplified form acceptable", i.v1 >= 1.5 ? "warn" : "ok", "Use extended Bernoulli when proximal velocity is about 1.5 m/s or more.") }; };
  F["poiseuille"] = function (i) { var v = Math.pow(i.r, 4); return { v: r(v, 0), g: grade("Relative teaching index", "ok", "Flow is proportional to radius to the fourth, pressure difference, and inverse length and viscosity. Doubling radius raises flow 16 fold.") }; };
  F["pulse-repetition"] = function (i) { var prf = 154000 / (2 * i.depth); var nyqHz = prf / 2; var v = nyqHz * 1540 / (2 * i.f0 * 1e6 * Math.cos(i.theta * Math.PI / 180)) * 100; return { v: r(v / 100, 2), extra: "Max PRF " + r(prf / 1000, 1) + " kHz at " + i.depth + " cm", g: grade("Physics result", "ok", "Deeper targets force a lower PRF and a lower Nyquist velocity. Lower frequency or baseline shift helps aliasing.") }; };
  F["pulse-geometry"] = function (i) { var lam = 1540 / (i.f0 * 1e6) * 1000; var spl = i.cycles * lam; var axial = spl / 2; var lat = lam * (i.depth / i.aperture); return { v: r(axial, 2), extra: "Wavelength " + r(lam, 2) + " mm, lateral resolution about " + r(lat, 1) + " mm at focus", g: grade("Physics result", "ok", "Shorter pulses (fewer cycles, higher frequency) improve axial resolution.") }; };
  F["acoustic"] = function (i) { var lam = 1540 / (i.f0 * 1e6) * 1000; var rc = Math.pow((i.z2 - i.z1) / (i.z2 + i.z1), 2) * 100; return { v: r(lam, 2), extra: "Reflected intensity " + r(rc, 1) + " percent at normal incidence", g: grade(rc > 50 ? "Strong reflector (air or bone like mismatch)" : "Soft tissue like mismatch", "ok", "Wavelength in mm; soft tissue impedances cluster near 1.5 MRayl, air is near zero, hence near total reflection.") }; };
  F["wave-relations"] = function (i) { var period = 1 / (i.f0); var lam = i.c / (i.f0 * 1e6) * 1000; return { v: r(period, 3), extra: "Wavelength " + r(lam, 2) + " mm at speed " + i.c + " m/s", g: grade("Physics result", "ok", "Frequency is set by the probe; speed and therefore wavelength are set by the medium.") }; };
  F["pathway-diastology"] = function (i) { var v = ee(i.e, i.sept, i.lat); var d = diaGrade(v, i.lavi, i.trv); var ea = i.e / i.a; var concl = d.tone === "bad" ? "Raised filling pressure. " : d.tone === "warn" ? "Indeterminate filling pressure. " : "Normal filling pressure. "; concl += ea >= 2 ? "E/A pattern suggests grade III inflow." : ea >= 0.8 ? "E/A pattern sits in the impaired relaxation to pseudonormal range; the four variable vote decides." : "E/A pattern suggests impaired relaxation, grade I, if pressure is normal."; return { v: r(v, 1), g: grade(concl, d.tone, d.detail + " Integrated ASE/EACVI 2016 pathway: the vote and the inflow pattern are both shown so the reasoning can be checked.") }; };
  F["pathway-as"] = function (i) { var hg = i.peakv >= 4 && i.meanG >= 40; var concl, tone; if (hg && i.ava < 1) { concl = "High gradient severe AS."; tone = "bad"; } else if (i.ava < 1 && i.svi <= 35 && i.lvef < 50) { concl = "Classical low flow low gradient AS: dobutamine echo decides true severe."; tone = "warn"; } else if (i.ava < 1 && i.svi <= 35) { concl = "Paradoxical low flow low gradient AS: check calcium score and measurement errors."; tone = "warn"; } else if (i.ava < 1) { concl = "Discordant AS: remeasure LVOT, then calcium score."; tone = "warn"; } else { concl = "Not severe by area: grade by velocity and gradient."; tone = "ok"; } return { v: r(i.meanG, 0), g: grade(concl, tone, "ESC/EACTS 2021 integrated AS pathway: velocity, gradient, area, flow (SVi 35) and EF together.") }; };
  F["pathway-mr"] = function (i) { var sev = i.eroa >= 0.40 && i.rvol >= 60; return { v: r(i.eroa, 2), g: grade(sev ? "Severe primary MR range (all agree)" : i.eroa >= 0.30 ? "Severe secondary MR range possible: state mechanism" : i.eroa >= 0.20 ? "Moderate MR range" : "Mild MR range", sev ? "bad" : i.eroa >= 0.20 ? "warn" : "ok", "ASE 2017: primary severe EROA 0.40 cm2 and volume 60 mL; vena contracta 7 mm or more supports severe. Secondary cut offs are lower.") }; };

  var CALCS = [{"id": "bsa", "name": "Body surface area", "cat": "Basics", "view": "tte_a4c", "source": "Du Bois 1916; Mosteller 1987", "inputs": [{"k": "h", "l": "Height", "u": "cm", "d": 170, "lo": 80, "hi": 230}, {"k": "w", "l": "Weight", "u": "kg", "d": 70, "lo": 2, "hi": 300}], "out": {"l": "BSA", "u": "m²"}, "example": {"h": 170, "w": 70}, "how": "Mosteller: BSA = square root of (height in cm times weight in kg divided by 3600). Du Bois is offered in the notes for comparison.", "limits": "BSA indexing fails at extremes of obesity. Use the same formula for serial studies.", "fig": "body"}, {"id": "lv-mass", "name": "LV mass and index", "cat": "Chambers", "view": "tte_plax", "source": "ASE/EACVI Chamber Quantification 2015", "inputs": [{"k": "lvid", "l": "LVIDd", "u": "cm", "d": 5.0, "lo": 2.5, "hi": 8.5}, {"k": "ivs", "l": "IVSd", "u": "cm", "d": 1.0, "lo": 0.4, "hi": 2.5}, {"k": "pw", "l": "PWd", "u": "cm", "d": 1.0, "lo": 0.4, "hi": 2.5}, {"k": "bsa", "l": "BSA", "u": "m²", "d": 1.8, "lo": 0.5, "hi": 3.0}], "out": {"l": "LV mass index", "u": "g/m²"}, "example": {"lvid": 5.0, "ivs": 1.0, "pw": 1.0, "bsa": 1.9}, "how": "Cube formula with the ASE corrected coefficient. Mass is indexed to BSA and graded by sex in the full pathway; this screen uses the adult cut offs in the grading panel.", "limits": "Assumes a prolate ellipsoid. Avoid in distorted ventricles; 2D or 3D mass is preferred there.", "fig": "plax"}, {"id": "lv-ef", "name": "LV ejection fraction (Simpson)", "cat": "Chambers", "view": "tte_a4c", "source": "ASE/EACVI Chamber Quantification 2015", "inputs": [{"k": "edv", "l": "End diastolic volume", "u": "mL", "d": 120, "lo": 20, "hi": 400}, {"k": "esv", "l": "End systolic volume", "u": "mL", "d": 50, "lo": 5, "hi": 300}], "out": {"l": "LVEF", "u": "%"}, "example": {"edv": 120, "esv": 50}, "how": "EF equals (EDV minus ESV) divided by EDV, times 100. Trace endocardium in apical four and two chamber views and average.", "limits": "Foreshortening and poor endocardial definition are the main errors. Contrast helps when two or more segments are unseen.", "fig": "a4c"}, {"id": "lv-volume-index", "name": "LV volumes indexed", "cat": "Chambers", "view": "tte_a4c", "source": "ASE/EACVI Chamber Quantification 2015", "inputs": [{"k": "edv", "l": "End diastolic volume", "u": "mL", "d": 120, "lo": 20, "hi": 400}, {"k": "esv", "l": "End systolic volume", "u": "mL", "d": 50, "lo": 5, "hi": 300}, {"k": "bsa", "l": "BSA", "u": "m²", "d": 1.8, "lo": 0.5, "hi": 3.0}], "out": {"l": "LVEDV index", "u": "mL/m²"}, "example": {"edv": 120, "esv": 50, "bsa": 1.8}, "how": "Volumes divided by BSA. Normal indexed values separate dilation from a large body habitus.", "limits": "Indexing can mask dilation in obesity. Report absolute volumes too.", "fig": "a4c"}, {"id": "lv-linear", "name": "LV linear dimensions and fractional shortening", "cat": "Chambers", "view": "tte_plax", "source": "ASE/EACVI Chamber Quantification 2015", "inputs": [{"k": "lvid", "l": "LVIDd", "u": "cm", "d": 5.0, "lo": 2.5, "hi": 8.5}, {"k": "lvids", "l": "LVIDs", "u": "cm", "d": 3.2, "lo": 1.5, "hi": 7.0}, {"k": "bsa", "l": "BSA", "u": "m²", "d": 1.8, "lo": 0.5, "hi": 3.0}], "out": {"l": "Fractional shortening", "u": "%"}, "example": {"lvid": 5.0, "lvids": 3.2, "bsa": 1.8}, "how": "Measure at the mitral leaflet tips, perpendicular to the long axis. Fractional shortening equals (LVIDd minus LVIDs) divided by LVIDd.", "limits": "Invalid with regional wall motion abnormality or dyssynchrony. Prefer volumetric EF.", "fig": "plax"}, {"id": "fractional-shortening", "name": "Fractional shortening (quick)", "cat": "Chambers", "view": "tte_plax", "source": "ASE/EACVI Chamber Quantification 2015", "inputs": [{"k": "lvid", "l": "LVIDd", "u": "cm", "d": 5.0, "lo": 2.5, "hi": 8.5}, {"k": "lvids", "l": "LVIDs", "u": "cm", "d": 3.2, "lo": 1.5, "hi": 7.0}], "out": {"l": "Fractional shortening", "u": "%"}, "example": {"lvid": 5.0, "lvids": 3.2}, "how": "Same formula as LV linear, kept as a rapid bedside screen.", "limits": "See LV linear limitations.", "fig": "plax"}, {"id": "lv-gls", "name": "LV global longitudinal strain", "cat": "Chambers", "view": "tte_a4c", "source": "ASE/EACVI Chamber Quantification 2015", "inputs": [{"k": "gls", "l": "GLS (enter as positive number)", "u": "%", "d": 18, "lo": 0, "hi": 35}], "out": {"l": "GLS magnitude", "u": "%"}, "example": {"gls": 18}, "how": "Speckle tracking average of 17 segments. More negative is better; this screen takes the magnitude and restores the sign in the result.", "limits": "Vendor values differ. Follow the same vendor serially; a relative fall over 15 percent is significant.", "fig": "a4c"}, {"id": "la-size", "name": "Left atrial size", "cat": "Chambers", "view": "tte_a4c", "source": "ASE/EACVI Chamber Quantification 2015", "inputs": [{"k": "lavi", "l": "LA volume index", "u": "mL/m²", "d": 28, "lo": 5, "hi": 120}, {"k": "lad", "l": "LA diameter (PLAX)", "u": "cm", "d": 3.8, "lo": 2.0, "hi": 7.0}], "out": {"l": "LA volume index", "u": "mL/m²"}, "example": {"lavi": 28, "lad": 3.8}, "how": "Biplane volume at end systole, indexed to BSA. Diameter alone is not recommended.", "limits": "Exclude the appendage and pulmonary vein confluence. Measure in dedicated LA views.", "fig": "a4c"}, {"id": "ra-size", "name": "Right atrial size", "cat": "Chambers", "view": "tte_a4c_rv_focus", "source": "BSE and ASE Right Heart Guidelines", "inputs": [{"k": "raa", "l": "RA area", "u": "cm²", "d": 16, "lo": 5, "hi": 50}, {"k": "ravi", "l": "RA volume index", "u": "mL/m²", "d": 25, "lo": 5, "hi": 100}], "out": {"l": "RA area", "u": "cm²"}, "example": {"raa": 16, "ravi": 25}, "how": "RV focused apical view at end systole. Area and indexed volume grade enlargement.", "limits": "Do not use the LV focused view; it understates RA size.", "fig": "rv"}, {"id": "rv-size", "name": "RV size", "cat": "Right heart", "view": "tte_a4c_rv_focus", "source": "BSE and ASE Right Heart Guidelines", "inputs": [{"k": "rvd1", "l": "Basal RV diameter RVD1", "u": "mm", "d": 38, "lo": 15, "hi": 70}, {"k": "rvd2", "l": "Mid RV diameter RVD2", "u": "mm", "d": 30, "lo": 10, "hi": 60}, {"k": "rvl", "l": "RV length", "u": "mm", "d": 75, "lo": 40, "hi": 120}], "out": {"l": "Basal RV diameter", "u": "mm"}, "example": {"rvd1": 38, "rvd2": 30, "rvl": 75}, "how": "RV focused view at end diastole. Basal diameter grades size; length helps spot foreshortening.", "limits": "RV size alone does not grade function. Pair with FAC, TAPSE or strain.", "fig": "rv"}, {"id": "rv-function", "name": "RV function (FAC, TAPSE, S prime)", "cat": "Right heart", "view": "tte_a4c_rv_focus", "source": "BSE and ASE Right Heart Guidelines", "inputs": [{"k": "eda", "l": "RV end diastolic area", "u": "cm²", "d": 20, "lo": 5, "hi": 50}, {"k": "esa", "l": "RV end systolic area", "u": "cm²", "d": 12, "lo": 3, "hi": 40}, {"k": "tapse", "l": "TAPSE", "u": "mm", "d": 20, "lo": 3, "hi": 35}, {"k": "sp", "l": "RV S prime", "u": "cm/s", "d": 12, "lo": 3, "hi": 25}], "out": {"l": "Fractional area change", "u": "%"}, "example": {"eda": 20, "esa": 12, "tapse": 20, "sp": 12}, "how": "FAC equals (EDA minus ESA) divided by EDA. TAPSE and S prime are longitudinal surrogates; agree or explain discordance.", "limits": "FAC needs the full RV including the outflow tract excluded consistently. TAPSE is angle and load dependent.", "fig": "rv"}, {"id": "aortic-size", "name": "Aortic size", "cat": "Chambers", "view": "tte_plax", "source": "ASE/EACVI Chamber Quantification 2015", "inputs": [{"k": "ann", "l": "Annulus", "u": "mm", "d": 24, "lo": 12, "hi": 40}, {"k": "sinus", "l": "Sinuses of Valsalva", "u": "mm", "d": 34, "lo": 18, "hi": 60}, {"k": "stj", "l": "Sinotubular junction", "u": "mm", "d": 30, "lo": 15, "hi": 55}, {"k": "asc", "l": "Ascending aorta", "u": "mm", "d": 34, "lo": 18, "hi": 65}, {"k": "bsa", "l": "BSA", "u": "m²", "d": 1.8, "lo": 0.5, "hi": 3.0}], "out": {"l": "Ascending aorta index", "u": "mm/m²"}, "example": {"ann": 24, "sinus": 34, "stj": 30, "asc": 34, "bsa": 1.8}, "how": "Leading edge to leading edge at end diastole in PLAX. Indexing helps in small or large patients.", "limits": "Measure perpendicular to the long axis. CT or MR for serial surgical thresholds.", "fig": "plax"}, {"id": "annulus-reversus", "name": "Annulus reversus check", "cat": "Diastology", "view": "tte_a4c", "source": "ASE/EACVI Diastolic Function 2016", "inputs": [{"k": "sept", "l": "Septal e prime", "u": "cm/s", "d": 6, "lo": 1, "hi": 25}, {"k": "lat", "l": "Lateral e prime", "u": "cm/s", "d": 5, "lo": 1, "hi": 25}], "out": {"l": "Septal minus lateral e prime", "u": "cm/s"}, "example": {"sept": 6, "lat": 5}, "how": "Normally lateral e prime exceeds septal. Reversal supports constrictive physiology in the right clinical picture.", "limits": "A screening sign only. Needs respirophasic and hepatic vein data.", "fig": "a4c"}, {"id": "wmsi", "name": "Wall motion score index", "cat": "Chambers", "view": "tte_a4c", "source": "ASE/EACVI Chamber Quantification 2015", "inputs": [{"k": "s1", "l": "Segments scored normal (1)", "u": "count", "d": 12, "lo": 0, "hi": 17}, {"k": "s2", "l": "Segments hypokinetic (2)", "u": "count", "d": 3, "lo": 0, "hi": 17}, {"k": "s3", "l": "Segments akinetic (3)", "u": "count", "d": 2, "lo": 0, "hi": 17}, {"k": "s4", "l": "Segments dyskinetic (4)", "u": "count", "d": 0, "lo": 0, "hi": 17}], "out": {"l": "WMSI", "u": "index"}, "example": {"s1": 12, "s2": 3, "s3": 2, "s4": 0}, "how": "Sum of segment scores divided by segments visualised, 17 segment model. 1.0 is normal.", "limits": "Requires good visualisation of most segments. State how many were seen.", "fig": "a4c"}, {"id": "diastolic-sinus", "name": "Diastolic function in sinus rhythm", "cat": "Diastology", "view": "tte_a4c", "source": "ASE/EACVI Diastolic Function 2016", "inputs": [{"k": "e", "l": "Mitral E velocity", "u": "m/s", "d": 0.8, "lo": 0.1, "hi": 2.5}, {"k": "a", "l": "Mitral A velocity", "u": "m/s", "d": 0.6, "lo": 0.05, "hi": 2.5}, {"k": "sept", "l": "Septal e prime", "u": "cm/s", "d": 8, "lo": 1, "hi": 25}, {"k": "lat", "l": "Lateral e prime", "u": "cm/s", "d": 10, "lo": 1, "hi": 25}, {"k": "lavi", "l": "LA volume index", "u": "mL/m²", "d": 28, "lo": 5, "hi": 120}, {"k": "trv", "l": "TR velocity", "u": "m/s", "d": 2.4, "lo": 0.5, "hi": 5.0}], "out": {"l": "Average E/e prime", "u": "ratio"}, "example": {"e": 0.8, "a": 0.6, "sept": 8, "lat": 10, "lavi": 28, "trv": 2.4}, "how": "Four variable ASE/EACVI 2016 screen: average E/e prime, septal and lateral e prime, LA volume index and TR velocity. Majority rule grades the study.", "limits": "Does not apply in AF, MAC, prosthetic mitral valve or HCM without the dedicated pathway.", "fig": "a4c"}, {"id": "lap-ee", "name": "Left atrial pressure from E/e prime", "cat": "Diastology", "view": "tte_a4c", "source": "ASE/EACVI Diastolic Function 2016", "inputs": [{"k": "e", "l": "Mitral E velocity", "u": "m/s", "d": 0.9, "lo": 0.1, "hi": 2.5}, {"k": "sept", "l": "Septal e prime", "u": "cm/s", "d": 7, "lo": 1, "hi": 25}, {"k": "lat", "l": "Lateral e prime", "u": "cm/s", "d": 9, "lo": 1, "hi": 25}], "out": {"l": "Average E/e prime", "u": "ratio"}, "example": {"e": 0.9, "sept": 7, "lat": 9}, "how": "Average E/e prime estimates filling pressure. Values at or below 8 suggest normal pressure; 14 or above suggests raised pressure.", "limits": "Unreliable in MAC, mitral prosthesis and regional disease at the sampled annulus.", "fig": "a4c"}, {"id": "diastolic-af", "name": "Diastolic function in atrial fibrillation", "cat": "Diastology", "view": "tte_a4c", "source": "ASE/EACVI Diastolic Function 2016", "inputs": [{"k": "e", "l": "Mitral E velocity", "u": "m/s", "d": 1.0, "lo": 0.1, "hi": 2.5}, {"k": "sept", "l": "Septal e prime", "u": "cm/s", "d": 7, "lo": 1, "hi": 25}, {"k": "trv", "l": "TR velocity", "u": "m/s", "d": 2.6, "lo": 0.5, "hi": 5.0}, {"k": "lavi", "l": "LA volume index", "u": "mL/m²", "d": 36, "lo": 5, "hi": 120}, {"k": "dt", "l": "E deceleration time", "u": "ms", "d": 170, "lo": 60, "hi": 400}], "out": {"l": "Septal E/e prime", "u": "ratio"}, "example": {"e": 1.0, "sept": 7, "trv": 2.6, "lavi": 36, "dt": 170}, "how": "AF pathway: average 5 to 10 cycles. Septal E/e prime, TR velocity, LA volume and deceleration time vote on filling pressure.", "limits": "Rate control matters. Very short or long cycles mislead; average matched cycles.", "fig": "a4c"}, {"id": "diastolic-hcm", "name": "Diastolic function in HCM", "cat": "Diastology", "view": "tte_a4c", "source": "ASE/EACVI Diastolic Function 2016", "inputs": [{"k": "e", "l": "Mitral E velocity", "u": "m/s", "d": 0.9, "lo": 0.1, "hi": 2.5}, {"k": "sept", "l": "Septal e prime", "u": "cm/s", "d": 6, "lo": 1, "hi": 25}, {"k": "lat", "l": "Lateral e prime", "u": "cm/s", "d": 7, "lo": 1, "hi": 25}, {"k": "lavi", "l": "LA volume index", "u": "mL/m²", "d": 38, "lo": 5, "hi": 120}, {"k": "trv", "l": "TR velocity", "u": "m/s", "d": 2.6, "lo": 0.5, "hi": 5.0}], "out": {"l": "Average E/e prime", "u": "ratio"}, "example": {"e": 0.9, "sept": 6, "lat": 7, "lavi": 38, "trv": 2.6}, "how": "HCM pathway weights LA volume and TR velocity because e prime is often reduced by hypertrophy itself.", "limits": "Dynamic obstruction changes loading. Record outflow gradient alongside.", "fig": "a4c"}, {"id": "diastolic-mac", "name": "Diastolic function in mitral annular calcification", "cat": "Diastology", "view": "tte_a4c", "source": "ASE/EACVI Diastolic Function 2016", "inputs": [{"k": "e", "l": "Mitral E velocity", "u": "m/s", "d": 1.0, "lo": 0.1, "hi": 2.5}, {"k": "sept", "l": "Septal e prime", "u": "cm/s", "d": 6, "lo": 1, "hi": 25}, {"k": "lat", "l": "Lateral e prime", "u": "cm/s", "d": 6, "lo": 1, "hi": 25}, {"k": "lavi", "l": "LA volume index", "u": "mL/m²", "d": 36, "lo": 5, "hi": 120}, {"k": "trv", "l": "TR velocity", "u": "m/s", "d": 2.6, "lo": 0.5, "hi": 5.0}], "out": {"l": "Average E/e prime", "u": "ratio"}, "example": {"e": 1.0, "sept": 6, "lat": 6, "lavi": 36, "trv": 2.6}, "how": "In MAC, e prime is blunted by calcium. LA volume, TR velocity and pulmonary vein flow carry more weight.", "limits": "Heavy MAC also distorts E velocity. State the limitation in the report.", "fig": "a4c"}, {"id": "diastolic-mr", "name": "Filling pressure in mitral regurgitation", "cat": "Diastology", "view": "tte_a4c", "source": "ASE/EACVI Diastolic Function 2016", "inputs": [{"k": "e", "l": "Mitral E velocity", "u": "m/s", "d": 1.1, "lo": 0.1, "hi": 2.5}, {"k": "sept", "l": "Septal e prime", "u": "cm/s", "d": 8, "lo": 1, "hi": 25}, {"k": "lat", "l": "Lateral e prime", "u": "cm/s", "d": 10, "lo": 1, "hi": 25}, {"k": "lavi", "l": "LA volume index", "u": "mL/m²", "d": 40, "lo": 5, "hi": 120}, {"k": "trv", "l": "TR velocity", "u": "m/s", "d": 2.7, "lo": 0.5, "hi": 5.0}], "out": {"l": "Average E/e prime", "u": "ratio"}, "example": {"e": 1.1, "sept": 8, "lat": 10, "lavi": 40, "trv": 2.7}, "how": "Significant MR raises E velocity. E/e prime still tracks pressure when MR is accounted for, with LA volume support.", "limits": "In severe MR, use the integrated MR pathway and pulmonary vein flow.", "fig": "a4c"}, {"id": "diastolic-ms", "name": "Filling pressure in mitral stenosis", "cat": "Diastology", "view": "tte_a4c", "source": "ASE/EACVI Diastolic Function 2016", "inputs": [{"k": "mva", "l": "Mitral valve area", "u": "cm²", "d": 1.4, "lo": 0.3, "hi": 4.0}, {"k": "mg", "l": "Mean mitral gradient", "u": "mmHg", "d": 8, "lo": 1, "hi": 40}, {"k": "lavi", "l": "LA volume index", "u": "mL/m²", "d": 42, "lo": 5, "hi": 120}, {"k": "trv", "l": "TR velocity", "u": "m/s", "d": 2.8, "lo": 0.5, "hi": 5.0}], "out": {"l": "Mean mitral gradient", "u": "mmHg"}, "example": {"mva": 1.4, "mg": 8, "lavi": 42, "trv": 2.8}, "how": "In MS the gradient reflects both area and flow. LA pressure is inferred with LA size and pulmonary pressure.", "limits": "Heart rate dominates the gradient. Record rate with every MS study.", "fig": "a4c"}, {"id": "diastolic-ph", "name": "Diastolic assessment in pulmonary hypertension", "cat": "Diastology", "view": "tte_a4c", "source": "ASE/EACVI Diastolic Function 2016", "inputs": [{"k": "e", "l": "Mitral E velocity", "u": "m/s", "d": 0.7, "lo": 0.1, "hi": 2.5}, {"k": "sept", "l": "Septal e prime", "u": "cm/s", "d": 7, "lo": 1, "hi": 25}, {"k": "lat", "l": "Lateral e prime", "u": "cm/s", "d": 8, "lo": 1, "hi": 25}, {"k": "lavi", "l": "LA volume index", "u": "mL/m²", "d": 26, "lo": 5, "hi": 120}, {"k": "pasp", "l": "Estimated PASP", "u": "mmHg", "d": 55, "lo": 10, "hi": 150}], "out": {"l": "Average E/e prime", "u": "ratio"}, "example": {"e": 0.7, "sept": 7, "lat": 8, "lavi": 26, "pasp": 55}, "how": "Separates left sided filling pressure from precapillary PH using E/e prime and LA size.", "limits": "Septal flattening distorts septal e prime. Use lateral too.", "fig": "a4c"}, {"id": "diastolic-restrictive", "name": "Restrictive physiology screen", "cat": "Diastology", "view": "tte_a4c", "source": "ASE/EACVI Diastolic Function 2016", "inputs": [{"k": "e", "l": "Mitral E velocity", "u": "m/s", "d": 1.2, "lo": 0.1, "hi": 2.5}, {"k": "a", "l": "Mitral A velocity", "u": "m/s", "d": 0.4, "lo": 0.05, "hi": 2.0}, {"k": "sept", "l": "Septal e prime", "u": "cm/s", "d": 5, "lo": 1, "hi": 25}, {"k": "lat", "l": "Lateral e prime", "u": "cm/s", "d": 5, "lo": 1, "hi": 25}, {"k": "dt", "l": "Deceleration time", "u": "ms", "d": 140, "lo": 60, "hi": 400}], "out": {"l": "E/A ratio", "u": "ratio"}, "example": {"e": 1.2, "a": 0.4, "sept": 5, "lat": 5, "dt": 140}, "how": "Tall E, small A, short deceleration and low e prime support restriction in the right picture.", "limits": "Young athletic hearts mimic the inflow pattern. Tissue Doppler separates them.", "fig": "a4c"}, {"id": "diastolic-transplant", "name": "Diastolic function after heart transplant", "cat": "Diastology", "view": "tte_a4c", "source": "ASE/EACVI Diastolic Function 2016", "inputs": [{"k": "e", "l": "Mitral E velocity", "u": "m/s", "d": 1.0, "lo": 0.1, "hi": 2.5}, {"k": "sept", "l": "Septal e prime", "u": "cm/s", "d": 7, "lo": 1, "hi": 25}, {"k": "lat", "l": "Lateral e prime", "u": "cm/s", "d": 8, "lo": 1, "hi": 25}, {"k": "lavi", "l": "LA volume index", "u": "mL/m²", "d": 34, "lo": 5, "hi": 120}, {"k": "trv", "l": "TR velocity", "u": "m/s", "d": 2.5, "lo": 0.5, "hi": 5.0}], "out": {"l": "Average E/e prime", "u": "ratio"}, "example": {"e": 1.0, "sept": 7, "lat": 8, "lavi": 34, "trv": 2.5}, "how": "Early after transplant, restrictive patterns are common and settle. Serial change matters more than one grade.", "limits": "Biatrial anastomosis enlarges the atria. Trend, do not overcall one study.", "fig": "a4c"}, {"id": "diastolic-lvad", "name": "Diastolic assessment with LVAD", "cat": "Diastology", "view": "tte_a4c", "source": "ASE/EACVI Diastolic Function 2016", "inputs": [{"k": "e", "l": "Mitral E velocity", "u": "m/s", "d": 0.8, "lo": 0.1, "hi": 2.5}, {"k": "sept", "l": "Septal e prime", "u": "cm/s", "d": 7, "lo": 1, "hi": 25}, {"k": "lat", "l": "Lateral e prime", "u": "cm/s", "d": 8, "lo": 1, "hi": 25}, {"k": "lavi", "l": "LA volume index", "u": "mL/m²", "d": 32, "lo": 5, "hi": 120}, {"k": "trv", "l": "TR velocity", "u": "m/s", "d": 2.5, "lo": 0.5, "hi": 5.0}], "out": {"l": "Average E/e prime", "u": "ratio"}, "example": {"e": 0.8, "sept": 7, "lat": 8, "lavi": 32, "trv": 2.5}, "how": "Continuous flow unloading changes inflow. Interpret with device speed, aortic valve opening and septal position.", "limits": "Ramp studies need a protocol. This screen supports, never replaces, one.", "fig": "a4c"}, {"id": "diastolic-exercise", "name": "Exercise diastolic stress screen", "cat": "Diastology", "view": "tte_a4c", "source": "ASE/EACVI Diastolic Function 2016", "inputs": [{"k": "e", "l": "Exercise E velocity", "u": "m/s", "d": 1.2, "lo": 0.1, "hi": 2.5}, {"k": "sept", "l": "Exercise septal e prime", "u": "cm/s", "d": 8, "lo": 1, "hi": 25}, {"k": "trv", "l": "Exercise TR velocity", "u": "m/s", "d": 3.0, "lo": 0.5, "hi": 5.0}, {"k": "restEe", "l": "Rest average E/e prime", "u": "ratio", "d": 9, "lo": 2, "hi": 30}], "out": {"l": "Exercise septal E/e prime", "u": "ratio"}, "example": {"e": 1.2, "sept": 8, "trv": 3.0, "restEe": 9}, "how": "A raised exercise E/e prime with TR velocity over 2.8 m/s supports exercise induced raised filling pressure.", "limits": "E and A fuse at high rates. Acquire early in recovery where local protocol allows.", "fig": "a4c"}, {"id": "diastolic-tachycardia", "name": "Diastolic assessment in tachycardia", "cat": "Diastology", "view": "tte_a4c", "source": "ASE/EACVI Diastolic Function 2016", "inputs": [{"k": "e", "l": "Mitral E velocity (fused if needed)", "u": "m/s", "d": 1.0, "lo": 0.1, "hi": 2.5}, {"k": "sept", "l": "Septal e prime", "u": "cm/s", "d": 7, "lo": 1, "hi": 25}, {"k": "lat", "l": "Lateral e prime", "u": "cm/s", "d": 8, "lo": 1, "hi": 25}, {"k": "trv", "l": "TR velocity", "u": "m/s", "d": 2.6, "lo": 0.5, "hi": 5.0}, {"k": "hr", "l": "Heart rate", "u": "bpm", "d": 110, "lo": 30, "hi": 220}], "out": {"l": "Average E/e prime", "u": "ratio"}, "example": {"e": 1.0, "sept": 7, "lat": 8, "trv": 2.6, "hr": 110}, "how": "When E and A fuse, tissue Doppler, LA volume and TR velocity carry the assessment.", "limits": "Rate control and repeat study beat forcing a grade from fused inflow.", "fig": "a4c"}, {"id": "lap-mr", "name": "LA pressure clues in MR", "cat": "Diastology", "view": "tte_a4c", "source": "ASE/EACVI Diastolic Function 2016", "inputs": [{"k": "e", "l": "Mitral E velocity", "u": "m/s", "d": 1.1, "lo": 0.1, "hi": 2.5}, {"k": "sept", "l": "Septal e prime", "u": "cm/s", "d": 8, "lo": 1, "hi": 25}, {"k": "lat", "l": "Lateral e prime", "u": "cm/s", "d": 10, "lo": 1, "hi": 25}, {"k": "ardur", "l": "Pulmonary vein Ar duration minus mitral A duration", "u": "ms", "d": 20, "lo": -100, "hi": 200}], "out": {"l": "Average E/e prime", "u": "ratio"}, "example": {"e": 1.1, "sept": 8, "lat": 10, "ardur": 20}, "how": "Ar duration exceeding mitral A duration by 30 ms or more supports raised LA pressure.", "limits": "Needs sinus rhythm and a clean pulmonary vein signal.", "fig": "a4c"}, {"id": "hepatic-reversal", "name": "Hepatic vein expiratory reversal (constriction)", "cat": "Pericardium", "view": "tte_subcostal_hepatic_vein", "source": "ASE/EACVI Diastolic Function 2016", "inputs": [{"k": "fwd", "l": "Expiratory diastolic forward velocity", "u": "cm/s", "d": 40, "lo": 1, "hi": 150}, {"k": "rev", "l": "Expiratory diastolic reversal velocity", "u": "cm/s", "d": 18, "lo": 0, "hi": 120}], "out": {"l": "Reversal to forward ratio", "u": "ratio"}, "example": {"fwd": 40, "rev": 18}, "how": "A reversal ratio of 0.79 or more in expiration supports constriction in the Mayo criteria.", "limits": "Free breathing acquisition. Breath hold abolishes the sign.", "fig": "subcostal"}, {"id": "as-continuity", "name": "Aortic stenosis: continuity AVA", "cat": "Valves", "view": "tte_a5c", "source": "ESC/EACTS Valvular Heart Disease 2021", "inputs": [{"k": "lvotd", "l": "LVOT diameter", "u": "cm", "d": 2.0, "lo": 1.2, "hi": 3.0}, {"k": "lvotvti", "l": "LVOT VTI", "u": "cm", "d": 22, "lo": 5, "hi": 60}, {"k": "avvti", "l": "Aortic valve VTI", "u": "cm", "d": 95, "lo": 15, "hi": 200}, {"k": "peakv", "l": "Peak aortic velocity", "u": "m/s", "d": 4.2, "lo": 0.5, "hi": 7.0}, {"k": "meanG", "l": "Mean gradient", "u": "mmHg", "d": 42, "lo": 1, "hi": 120}], "out": {"l": "Aortic valve area", "u": "cm²"}, "example": {"lvotd": 2.0, "lvotvti": 22, "avvti": 95, "peakv": 4.2, "meanG": 42}, "how": "Continuity: AVA equals LVOT area times LVOT VTI divided by aortic VTI. Grade with peak velocity and mean gradient together.", "limits": "LVOT diameter is squared, so a 1 mm error moves AVA about 10 percent. Measure inner edge to inner edge in systole.", "fig": "a5c"}, {"id": "lvot-flow", "name": "LVOT flow and stroke volume", "cat": "Valves", "view": "tte_a5c", "source": "ESC/EACTS Valvular Heart Disease 2021", "inputs": [{"k": "lvotd", "l": "LVOT diameter", "u": "cm", "d": 2.0, "lo": 1.2, "hi": 3.0}, {"k": "lvotvti", "l": "LVOT VTI", "u": "cm", "d": 22, "lo": 5, "hi": 60}, {"k": "bsa", "l": "BSA", "u": "m²", "d": 1.8, "lo": 0.5, "hi": 3.0}, {"k": "hr", "l": "Heart rate", "u": "bpm", "d": 70, "lo": 30, "hi": 200}], "out": {"l": "Stroke volume index", "u": "mL/m²"}, "example": {"lvotd": 2.0, "lvotvti": 22, "bsa": 1.8, "hr": 70}, "how": "Stroke volume equals LVOT area times VTI. Low flow is an indexed stroke volume at or below 35 mL per m².", "limits": "Sample just below the valve, laminar flow, parallel to the jet.", "fig": "a5c"}, {"id": "ar-continuity", "name": "Aortic regurgitation: continuity clues", "cat": "Valves", "view": "tte_a5c", "source": "ASE Native Valve Regurgitation 2017", "inputs": [{"k": "lvotd", "l": "LVOT diameter", "u": "cm", "d": 2.1, "lo": 1.2, "hi": 3.0}, {"k": "lvotvti", "l": "LVOT VTI", "u": "cm", "d": 26, "lo": 5, "hi": 70}, {"k": "svVol", "l": "Simpson stroke volume", "u": "mL", "d": 95, "lo": 20, "hi": 250}], "out": {"l": "Regurgitant volume estimate", "u": "mL"}, "example": {"lvotd": 2.1, "lvotvti": 26, "svVol": 95}, "how": "Forward LVOT stroke volume minus volumetric stroke volume estimates regurgitant volume when only AR is present.", "limits": "Fails with mitral regurgitation or shunt. Use PISA and vena contracta too.", "fig": "a5c"}, {"id": "ar-pisa", "name": "Aortic regurgitation PISA", "cat": "Valves", "view": "tte_plax", "source": "ASE Native Valve Regurgitation 2017", "inputs": [{"k": "r", "l": "PISA radius", "u": "cm", "d": 0.7, "lo": 0.1, "hi": 2.0}, {"k": "va", "l": "Aliasing velocity", "u": "cm/s", "d": 35, "lo": 10, "hi": 80}, {"k": "peakv", "l": "Peak AR velocity", "u": "m/s", "d": 4.0, "lo": 1.0, "hi": 7.0}, {"k": "vti", "l": "AR VTI", "u": "cm", "d": 180, "lo": 30, "hi": 400}], "out": {"l": "Effective regurgitant orifice area", "u": "cm²"}, "example": {"r": 0.7, "va": 35, "peakv": 4.0, "vti": 180}, "how": "Flow equals 2 pi r squared times aliasing velocity. EROA equals flow divided by peak velocity; volume equals EROA times VTI.", "limits": "AR PISA is technically hard and angle dependent. Confirm with vena contracta and holodiastolic reversal.", "fig": "plax"}, {"id": "mr-pisa", "name": "Mitral regurgitation PISA", "cat": "Valves", "view": "tte_a4c", "source": "ASE Native Valve Regurgitation 2017", "inputs": [{"k": "r", "l": "PISA radius", "u": "cm", "d": 0.8, "lo": 0.1, "hi": 2.0}, {"k": "va", "l": "Aliasing velocity", "u": "cm/s", "d": 35, "lo": 10, "hi": 80}, {"k": "peakv", "l": "Peak MR velocity", "u": "m/s", "d": 5.0, "lo": 2.0, "hi": 8.0}, {"k": "vti", "l": "MR VTI", "u": "cm", "d": 150, "lo": 30, "hi": 300}], "out": {"l": "Effective regurgitant orifice area", "u": "cm²"}, "example": {"r": 0.8, "va": 35, "peakv": 5.0, "vti": 150}, "how": "Flow equals 2 pi r squared times aliasing velocity. EROA equals flow divided by peak MR velocity. Volume equals EROA times MR VTI.", "limits": "Assumes a hemispheric shell and a round orifice. Eccentric and late systolic MR mislead.", "fig": "a4c"}, {"id": "mr-continuity", "name": "Mitral regurgitation: continuity volume", "cat": "Valves", "view": "tte_a4c", "source": "ASE Native Valve Regurgitation 2017", "inputs": [{"k": "mvd", "l": "Mitral annulus diameter", "u": "cm", "d": 3.2, "lo": 2.0, "hi": 5.0}, {"k": "mvvti", "l": "Mitral inflow VTI", "u": "cm", "d": 28, "lo": 5, "hi": 80}, {"k": "lvotd", "l": "LVOT diameter", "u": "cm", "d": 2.0, "lo": 1.2, "hi": 3.0}, {"k": "lvotvti", "l": "LVOT VTI", "u": "cm", "d": 22, "lo": 5, "hi": 60}], "out": {"l": "Regurgitant volume", "u": "mL"}, "example": {"mvd": 3.2, "mvvti": 28, "lvotd": 2.0, "lvotvti": 22}, "how": "Mitral stroke volume minus LVOT stroke volume equals regurgitant volume when no AR or shunt.", "limits": "Annulus is elliptical, so this is supportive only. PISA is preferred.", "fig": "a4c"}, {"id": "mitral-pht", "name": "Mitral stenosis: pressure half time", "cat": "Valves", "view": "tte_a4c", "source": "ESC/EACTS Valvular Heart Disease 2021", "inputs": [{"k": "pht", "l": "Pressure half time", "u": "ms", "d": 150, "lo": 30, "hi": 500}], "out": {"l": "Mitral valve area", "u": "cm²"}, "example": {"pht": 150}, "how": "MVA equals 220 divided by pressure half time in ms. Grade area with mean gradient and symptoms.", "limits": "Invalid early after valvuloplasty, in AR, or with abnormal compliance. Planimetry is preferred.", "fig": "a4c"}, {"id": "mitral-pisa", "name": "Mitral stenosis PISA", "cat": "Valves", "view": "tte_a4c", "source": "ESC/EACTS Valvular Heart Disease 2021", "inputs": [{"k": "r", "l": "PISA radius", "u": "cm", "d": 0.9, "lo": 0.2, "hi": 2.0}, {"k": "va", "l": "Aliasing velocity", "u": "cm/s", "d": 30, "lo": 10, "hi": 80}, {"k": "peakv", "l": "Peak mitral E velocity", "u": "m/s", "d": 1.8, "lo": 0.5, "hi": 4.0}, {"k": "angle", "l": "Leaflet opening angle", "u": "degrees", "d": 110, "lo": 60, "hi": 180}], "out": {"l": "Mitral valve area (PISA)", "u": "cm²"}, "example": {"r": 0.9, "va": 30, "peakv": 1.8, "angle": 110}, "how": "Flow corrected by angle over 180, divided by peak velocity. Useful when planimetry fails.", "limits": "Angle correction is operator dependent.", "fig": "a4c"}, {"id": "mitral-continuity", "name": "Mitral valve area by continuity", "cat": "Valves", "view": "tte_a5c", "source": "ESC/EACTS Valvular Heart Disease 2021", "inputs": [{"k": "lvotd", "l": "LVOT diameter", "u": "cm", "d": 2.0, "lo": 1.2, "hi": 3.0}, {"k": "lvotvti", "l": "LVOT VTI", "u": "cm", "d": 22, "lo": 5, "hi": 60}, {"k": "mvvti", "l": "Mitral VTI", "u": "cm", "d": 55, "lo": 10, "hi": 150}], "out": {"l": "Mitral valve area", "u": "cm²"}, "example": {"lvotd": 2.0, "lvotvti": 22, "mvvti": 55}, "how": "Stroke volume divided by mitral VTI. Valid only without significant MR or AR.", "limits": "Any regurgitation breaks continuity. Say so in the report.", "fig": "a5c"}, {"id": "tr-pisa", "name": "Tricuspid regurgitation PISA", "cat": "Valves", "view": "tte_a4c_rv_focus", "source": "ASE Native Valve Regurgitation 2017", "inputs": [{"k": "r", "l": "PISA radius", "u": "cm", "d": 0.7, "lo": 0.1, "hi": 2.0}, {"k": "va", "l": "Aliasing velocity", "u": "cm/s", "d": 28, "lo": 10, "hi": 70}, {"k": "peakv", "l": "Peak TR velocity", "u": "m/s", "d": 3.0, "lo": 1.0, "hi": 6.0}, {"k": "vti", "l": "TR VTI", "u": "cm", "d": 90, "lo": 20, "hi": 250}], "out": {"l": "Effective regurgitant orifice area", "u": "cm²"}, "example": {"r": 0.7, "va": 28, "peakv": 3.0, "vti": 90}, "how": "Same PISA physics on the right side, usually at a lower aliasing velocity.", "limits": "TR orifice is often non circular. Use vena contracta width and hepatic flow too.", "fig": "rv"}, {"id": "tricuspid-stenosis", "name": "Tricuspid stenosis", "cat": "Valves", "view": "tte_a4c_rv_focus", "source": "ESC/EACTS Valvular Heart Disease 2021", "inputs": [{"k": "meanG", "l": "Mean tricuspid gradient", "u": "mmHg", "d": 6, "lo": 0.5, "hi": 25}, {"k": "vti", "l": "Tricuspid inflow VTI", "u": "cm", "d": 60, "lo": 10, "hi": 150}, {"k": "pht", "l": "Pressure half time", "u": "ms", "d": 220, "lo": 50, "hi": 500}], "out": {"l": "Mean gradient", "u": "mmHg"}, "example": {"meanG": 6, "vti": 60, "pht": 220}, "how": "A mean gradient of 5 mmHg or more at normal rate supports significant stenosis.", "limits": "Respiration and rate move the gradient. Average 5 beats.", "fig": "rv"}, {"id": "pulmonic-stenosis", "name": "Pulmonic stenosis", "cat": "Valves", "view": "tte_psax_av", "source": "ESC/EACTS Valvular Heart Disease 2021", "inputs": [{"k": "peakv", "l": "Peak pulmonic velocity", "u": "m/s", "d": 3.2, "lo": 0.5, "hi": 6.0}, {"k": "meanG", "l": "Mean gradient", "u": "mmHg", "d": 22, "lo": 1, "hi": 100}], "out": {"l": "Peak gradient", "u": "mmHg"}, "example": {"peakv": 3.2, "meanG": 22}, "how": "Simplified Bernoulli peak gradient equals 4 v squared. Grade with peak velocity.", "limits": "Dynamic infundibular obstruction differs from valvar stenosis. Inspect anatomy.", "fig": "psax"}, {"id": "pulmonic-regurg", "name": "Pulmonic regurgitation severity clues", "cat": "Valves", "view": "tte_psax_av", "source": "ASE Native Valve Regurgitation 2017", "inputs": [{"k": "prEndV", "l": "End diastolic PR velocity", "u": "m/s", "d": 1.8, "lo": 0.3, "hi": 4.0}, {"k": "rapEst", "l": "Estimated RA pressure", "u": "mmHg", "d": 8, "lo": 3, "hi": 25}, {"k": "jetW", "l": "PR jet width to RVOT ratio", "u": "ratio", "d": 0.5, "lo": 0.05, "hi": 1.0}], "out": {"l": "Estimated diastolic PA pressure", "u": "mmHg"}, "example": {"prEndV": 1.8, "rapEst": 8, "jetW": 0.5}, "how": "End diastolic gradient plus RA pressure estimates PA diastolic pressure. Jet width ratio supports severity.", "limits": "PR severity is multiparametric. Short deceleration and diastolic flow reversal matter.", "fig": "psax"}, {"id": "lv-pressure", "name": "LV pressure clues (MR and AR jets)", "cat": "Valves", "view": "tte_a4c", "source": "ESC/EACTS Valvular Heart Disease 2021", "inputs": [{"k": "mrv", "l": "Peak MR velocity", "u": "m/s", "d": 5.0, "lo": 2.0, "hi": 8.0}, {"k": "lapEst", "l": "Estimated LA pressure", "u": "mmHg", "d": 15, "lo": 3, "hi": 50}, {"k": "sbp", "l": "Systolic blood pressure", "u": "mmHg", "d": 120, "lo": 60, "hi": 250}, {"k": "arv", "l": "Peak AR velocity", "u": "m/s", "d": 4.0, "lo": 1.0, "hi": 7.0}, {"k": "dbp", "l": "Diastolic blood pressure", "u": "mmHg", "d": 70, "lo": 30, "hi": 150}], "out": {"l": "Estimated LV systolic pressure check", "u": "mmHg"}, "example": {"mrv": 5.0, "lapEst": 15, "sbp": 120, "arv": 4.0, "dbp": 70}, "how": "MR gradient plus LA pressure should match cuff systolic pressure. AR gradient subtracted from diastolic pressure estimates LVEDP.", "limits": "A mismatch means a bad envelope, wrong cuff pressure, or wrong LA estimate.", "fig": "a4c"}, {"id": "aortic-prosthesis", "name": "Aortic prosthesis assessment", "cat": "Prostheses", "view": "tte_a5c", "source": "ASE Prosthetic Valves 2024", "inputs": [{"k": "peakv", "l": "Peak prosthesis velocity", "u": "m/s", "d": 2.8, "lo": 0.5, "hi": 6.0}, {"k": "meanG", "l": "Mean gradient", "u": "mmHg", "d": 18, "lo": 1, "hi": 100}, {"k": "lvotvti", "l": "LVOT VTI", "u": "cm", "d": 22, "lo": 5, "hi": 60}, {"k": "avvti", "l": "Prosthesis VTI", "u": "cm", "d": 48, "lo": 10, "hi": 150}, {"k": "lvotd", "l": "LVOT diameter", "u": "cm", "d": 2.0, "lo": 1.2, "hi": 3.0}], "out": {"l": "Doppler velocity index", "u": "ratio"}, "example": {"peakv": 2.8, "meanG": 18, "lvotvti": 22, "avvti": 48, "lvotd": 2.0}, "how": "DVI equals LVOT VTI divided by prosthesis VTI. Continuity EOA uses the LVOT just below the sewing ring.", "limits": "Patient prosthesis mismatch needs indexed EOA and the reference table for the valve model and size.", "fig": "a5c"}, {"id": "aortic-prosthesis-screen", "name": "Aortic prosthesis: screen vs full", "cat": "Prostheses", "view": "tte_a5c", "source": "ASE Prosthetic Valves 2024", "inputs": [{"k": "peakv", "l": "Peak velocity", "u": "m/s", "d": 2.4, "lo": 0.5, "hi": 6.0}, {"k": "meanG", "l": "Mean gradient", "u": "mmHg", "d": 12, "lo": 1, "hi": 100}, {"k": "dvi", "l": "Doppler velocity index", "u": "ratio", "d": 0.45, "lo": 0.1, "hi": 1.0}, {"k": "at", "l": "Acceleration time", "u": "ms", "d": 80, "lo": 30, "hi": 200}], "out": {"l": "Doppler velocity index", "u": "ratio"}, "example": {"peakv": 2.4, "meanG": 12, "dvi": 0.45, "at": 80}, "how": "Screen first: velocity, gradient, DVI and acceleration time. Abnormal screen triggers the full prosthesis study.", "limits": "Compare with the early post implant baseline, not population values alone.", "fig": "a5c"}, {"id": "aortic-prosthesis-serial", "name": "Aortic prosthesis: serial change", "cat": "Prostheses", "view": "tte_a5c", "source": "ASE Prosthetic Valves 2024", "inputs": [{"k": "curG", "l": "Current mean gradient", "u": "mmHg", "d": 22, "lo": 1, "hi": 100}, {"k": "baseG", "l": "Baseline mean gradient", "u": "mmHg", "d": 12, "lo": 1, "hi": 100}, {"k": "curV", "l": "Current peak velocity", "u": "m/s", "d": 3.2, "lo": 0.5, "hi": 6.0}, {"k": "baseV", "l": "Baseline peak velocity", "u": "m/s", "d": 2.4, "lo": 0.5, "hi": 6.0}], "out": {"l": "Rise in mean gradient", "u": "mmHg"}, "example": {"curG": 22, "baseG": 12, "curV": 3.2, "baseV": 2.4}, "how": "A rise in gradient with a fall in DVI suggests true dysfunction; a rise with stable DVI suggests high flow.", "limits": "Anaemia, fever and thyrotoxicosis raise gradients without dysfunction.", "fig": "a5c"}, {"id": "mitral-prosthesis", "name": "Mitral prosthesis assessment", "cat": "Prostheses", "view": "tte_a4c", "source": "ASE Prosthetic Valves 2024", "inputs": [{"k": "peakE", "l": "Peak E velocity", "u": "m/s", "d": 1.8, "lo": 0.3, "hi": 4.0}, {"k": "meanG", "l": "Mean gradient", "u": "mmHg", "d": 6, "lo": 0.5, "hi": 30}, {"k": "pht", "l": "Pressure half time", "u": "ms", "d": 130, "lo": 40, "hi": 400}, {"k": "vtiRatio", "l": "Mitral VTI to LVOT VTI ratio", "u": "ratio", "d": 1.8, "lo": 0.5, "hi": 5.0}], "out": {"l": "Mean gradient", "u": "mmHg"}, "example": {"peakE": 1.8, "meanG": 6, "pht": 130, "vtiRatio": 1.8}, "how": "Combine E velocity, mean gradient, PHT area and VTI ratio. No single number grades a mitral prosthesis.", "limits": "Rate and stroke volume move every value. Record both.", "fig": "a4c"}, {"id": "mitral-prosthesis-screen", "name": "Mitral prosthesis: screen vs full", "cat": "Prostheses", "view": "tte_a4c", "source": "ASE Prosthetic Valves 2024", "inputs": [{"k": "peakE", "l": "Peak E velocity", "u": "m/s", "d": 1.9, "lo": 0.3, "hi": 4.0}, {"k": "meanG", "l": "Mean gradient", "u": "mmHg", "d": 7, "lo": 0.5, "hi": 30}, {"k": "pht", "l": "Pressure half time", "u": "ms", "d": 160, "lo": 40, "hi": 400}], "out": {"l": "Pressure half time area", "u": "cm²"}, "example": {"peakE": 1.9, "meanG": 7, "pht": 160}, "how": "Screen with E velocity, gradient and PHT. Abnormal values need leaflet imaging and fluoroscopy or CT as advised.", "limits": "PHT area overestimates in many prostheses. Use it as a flag, not a verdict.", "fig": "a4c"}, {"id": "rap", "name": "Right atrial pressure from IVC", "cat": "Right heart", "view": "tte_subcostal_ivc", "source": "BSE and ASE Right Heart Guidelines", "inputs": [{"k": "ivcd", "l": "IVC diameter", "u": "mm", "d": 18, "lo": 5, "hi": 35}, {"k": "collapse", "l": "Inspiratory collapse", "u": "%", "d": 60, "lo": 0, "hi": 100}], "out": {"l": "Estimated RAP", "u": "mmHg"}, "example": {"ivcd": 18, "collapse": 60}, "how": "IVC size and collapse assign RAP of 3, 8 or 15 mmHg in the standard scheme.", "limits": "Ventilation, athletic hearts and raised intra abdominal pressure break the scheme.", "fig": "ivc"}, {"id": "rvsp", "name": "RV systolic pressure", "cat": "Right heart", "view": "tte_a4c", "source": "BSE and ASE Right Heart Guidelines", "inputs": [{"k": "trv", "l": "Max TR velocity", "u": "m/s", "d": 3.0, "lo": 0.5, "hi": 6.0}, {"k": "rap", "l": "Estimated RAP", "u": "mmHg", "d": 8, "lo": 0, "hi": 25}], "out": {"l": "RVSP", "u": "mmHg"}, "example": {"trv": 3.0, "rap": 8}, "how": "RVSP equals 4 times TR velocity squared, plus RAP. It equals PASP without RVOT obstruction.", "limits": "An incomplete TR envelope understates pressure. State signal quality.", "fig": "a4c"}, {"id": "pa-pressure", "name": "Pulmonary artery pressures (systolic, diastolic, mean)", "cat": "Right heart", "view": "tte_psax_av", "source": "BSE and ASE Right Heart Guidelines", "inputs": [{"k": "trv", "l": "Max TR velocity", "u": "m/s", "d": 3.0, "lo": 0.5, "hi": 6.0}, {"k": "rap", "l": "Estimated RAP", "u": "mmHg", "d": 8, "lo": 0, "hi": 25}, {"k": "prend", "l": "End diastolic PR velocity", "u": "m/s", "d": 1.5, "lo": 0.3, "hi": 4.0}, {"k": "pat", "l": "Pulmonary acceleration time", "u": "ms", "d": 110, "lo": 40, "hi": 250}], "out": {"l": "Mean PA pressure estimate", "u": "mmHg"}, "example": {"trv": 3.0, "rap": 8, "prend": 1.5, "pat": 110}, "how": "Systolic from TR, diastolic from end PR, mean from early PR or acceleration time. Cross check all three.", "limits": "Each estimate fails in a different lesion. Discordance is information.", "fig": "psax"}, {"id": "mpap-rvot", "name": "Mean PA pressure from RVOT", "cat": "Right heart", "view": "tte_psax_av", "source": "BSE and ASE Right Heart Guidelines", "inputs": [{"k": "pat", "l": "Pulmonary acceleration time", "u": "ms", "d": 95, "lo": 40, "hi": 250}, {"k": "peakpr", "l": "Peak early PR velocity", "u": "m/s", "d": 2.2, "lo": 0.5, "hi": 5.0}, {"k": "rap", "l": "Estimated RAP", "u": "mmHg", "d": 8, "lo": 0, "hi": 25}], "out": {"l": "Mean PA pressure (PR method)", "u": "mmHg"}, "example": {"pat": 95, "peakpr": 2.2, "rap": 8}, "how": "Mean pressure equals 4 times peak PR velocity squared plus RAP. Acceleration time supports it.", "limits": "Needs a measurable PR envelope, present in most PH studies.", "fig": "psax"}, {"id": "pvr", "name": "Pulmonary vascular resistance (echo estimate)", "cat": "Right heart", "view": "tte_a4c", "source": "BSE and ASE Right Heart Guidelines", "inputs": [{"k": "trv", "l": "Max TR velocity", "u": "m/s", "d": 3.2, "lo": 0.5, "hi": 6.0}, {"k": "rvotvti", "l": "RVOT VTI", "u": "cm", "d": 14, "lo": 3, "hi": 40}], "out": {"l": "PVR estimate", "u": "Wood units"}, "example": {"trv": 3.2, "rvotvti": 14}, "how": "Abbas formula: PVR equals TR velocity divided by RVOT VTI, times 10, plus 0.16. A screening estimate only.", "limits": "Not a catheter replacement. Very high or low values track better than mid range.", "fig": "a4c"}, {"id": "mpi", "name": "Myocardial performance index (Tei)", "cat": "Right heart", "view": "tte_a4c", "source": "BSE and ASE Right Heart Guidelines", "inputs": [{"k": "tco", "l": "Tricuspid closure to opening time", "u": "ms", "d": 380, "lo": 200, "hi": 600}, {"k": "et", "l": "RV ejection time", "u": "ms", "d": 280, "lo": 150, "hi": 450}], "out": {"l": "RV MPI", "u": "index"}, "example": {"tco": 380, "et": 280}, "how": "MPI equals (TCO minus ET) divided by ET, the isovolumic times over ejection time. The same formula serves the LV with mitral times.", "limits": "Heart rate and conduction delay alter MPI. Average matched beats.", "fig": "a4c"}, {"id": "qpqs", "name": "Qp to Qs ratio", "cat": "Shunts", "view": "tte_psax_av", "source": "BSE and ASE Right Heart Guidelines", "inputs": [{"k": "rvotd", "l": "RVOT diameter", "u": "cm", "d": 2.4, "lo": 1.0, "hi": 4.0}, {"k": "rvotvti", "l": "RVOT VTI", "u": "cm", "d": 18, "lo": 3, "hi": 50}, {"k": "lvotd", "l": "LVOT diameter", "u": "cm", "d": 2.0, "lo": 1.2, "hi": 3.0}, {"k": "lvotvti", "l": "LVOT VTI", "u": "cm", "d": 22, "lo": 5, "hi": 60}], "out": {"l": "Qp/Qs", "u": "ratio"}, "example": {"rvotd": 2.4, "rvotvti": 18, "lvotd": 2.0, "lvotvti": 22}, "how": "Pulmonary stroke volume over systemic stroke volume, each area times VTI. Diameter errors dominate.", "limits": "RVOT is elliptical. Use one consistent method and state it.", "fig": "psax"}, {"id": "asd", "name": "Atrial septal defect sizing clues", "cat": "Shunts", "view": "tte_subcostal_4c", "source": "ESC/EACTS Valvular Heart Disease 2021", "inputs": [{"k": "defect", "l": "Defect diameter", "u": "mm", "d": 14, "lo": 2, "hi": 45}, {"k": "rvd1", "l": "Basal RV diameter", "u": "mm", "d": 44, "lo": 15, "hi": 70}, {"k": "qpqs", "l": "Qp/Qs", "u": "ratio", "d": 1.8, "lo": 0.5, "hi": 5.0}], "out": {"l": "Qp/Qs (entered)", "u": "ratio"}, "example": {"defect": 14, "rvd1": 44, "qpqs": 1.8}, "how": "Size, rims, RV volume load and Qp/Qs together decide closure referral. This screen grades the shunt burden.", "limits": "Device sizing needs TEE or intracardiac echo. Never size from this screen alone.", "fig": "subcostal"}, {"id": "vsd-pressure", "name": "VSD gradient and LV pressure", "cat": "Shunts", "view": "tte_a5c", "source": "ESC/EACTS Valvular Heart Disease 2021", "inputs": [{"k": "vsdv", "l": "Peak VSD jet velocity", "u": "m/s", "d": 4.5, "lo": 0.5, "hi": 7.0}, {"k": "sbp", "l": "Systolic blood pressure", "u": "mmHg", "d": 115, "lo": 60, "hi": 250}], "out": {"l": "Estimated RV systolic pressure", "u": "mmHg"}, "example": {"vsdv": 4.5, "sbp": 115}, "how": "RV systolic pressure approx equals cuff systolic minus 4 v squared, when LV pressure equals cuff pressure.", "limits": "Fails with LVOT obstruction or a poor jet angle.", "fig": "a5c"}, {"id": "pda-pressure", "name": "PDA gradient and PA pressure", "cat": "Shunts", "view": "tte_suprasternal_ductal", "source": "ESC/EACTS Valvular Heart Disease 2021", "inputs": [{"k": "pdav", "l": "Peak PDA velocity", "u": "m/s", "d": 3.5, "lo": 0.5, "hi": 6.0}, {"k": "sbp", "l": "Systolic blood pressure", "u": "mmHg", "d": 110, "lo": 60, "hi": 250}, {"k": "pdavd", "l": "End diastolic PDA velocity", "u": "m/s", "d": 1.2, "lo": 0.2, "hi": 4.0}, {"k": "dbp", "l": "Diastolic blood pressure", "u": "mmHg", "d": 65, "lo": 30, "hi": 150}], "out": {"l": "Estimated PA systolic pressure", "u": "mmHg"}, "example": {"pdav": 3.5, "sbp": 110, "pdavd": 1.2, "dbp": 65}, "how": "Aortic minus ductal gradient estimates PA pressure in systole and diastole.", "limits": "Needs a ductal view with parallel alignment.", "fig": "ductal"}, {"id": "coarctation", "name": "Coarctation gradient", "cat": "Shunts", "view": "tte_suprasternal_arch_lax", "source": "ESC/EACTS Valvular Heart Disease 2021", "inputs": [{"k": "peakv", "l": "Peak descending aorta velocity", "u": "m/s", "d": 3.0, "lo": 0.5, "hi": 6.0}, {"k": "proxv", "l": "Proximal velocity", "u": "m/s", "d": 1.0, "lo": 0.2, "hi": 3.0}, {"k": "meanG", "l": "Mean gradient", "u": "mmHg", "d": 18, "lo": 1, "hi": 80}, {"k": "dbp", "l": "Arm diastolic pressure", "u": "mmHg", "d": 70, "lo": 30, "hi": 150}, {"k": "sbpArm", "l": "Arm systolic pressure", "u": "mmHg", "d": 130, "lo": 60, "hi": 250}, {"k": "sbpLeg", "l": "Leg systolic pressure", "u": "mmHg", "d": 100, "lo": 40, "hi": 250}], "out": {"l": "Peak gradient (extended Bernoulli)", "u": "mmHg"}, "example": {"peakv": 3.0, "proxv": 1.0, "meanG": 18, "dbp": 70, "sbpArm": 130, "sbpLeg": 100}, "how": "Extended Bernoulli subtracts proximal velocity. Diastolic run off and arm leg difference support significance.", "limits": "Collaterals lower the gradient in severe disease. Never grade on gradient alone.", "fig": "arch"}, {"id": "fontan-gradient", "name": "Fontan pathway gradient", "cat": "Shunts", "view": "tte_subcostal_4c", "source": "ESC/EACTS Valvular Heart Disease 2021", "inputs": [{"k": "peakv", "l": "Peak Fontan pathway velocity", "u": "m/s", "d": 1.2, "lo": 0.2, "hi": 4.0}, {"k": "meanG", "l": "Mean gradient", "u": "mmHg", "d": 3, "lo": 0.2, "hi": 20}], "out": {"l": "Peak gradient", "u": "mmHg"}, "example": {"peakv": 1.2, "meanG": 3}, "how": "Even small gradients matter in a Fontan circuit. Record respiration and fenestration flow.", "limits": "Low velocity circuits need careful Doppler scale and colour inspection.", "fig": "subcostal"}, {"id": "effusion-size", "name": "Pericardial effusion size", "cat": "Pericardium", "view": "tte_plax", "source": "ESC/EACTS Valvular Heart Disease 2021", "inputs": [{"k": "dias", "l": "End diastolic echo free space", "u": "mm", "d": 14, "lo": 0, "hi": 60}], "out": {"l": "Effusion depth", "u": "mm"}, "example": {"dias": 14}, "how": "Largest end diastolic space grades size: under 10 small, 10 to 20 moderate, over 20 large. Tamponade is clinical, not size alone.", "limits": "Loculated effusions break the grading. Scan all windows.", "fig": "plax"}, {"id": "mitral-respiratory", "name": "Mitral inflow respiratory variation", "cat": "Pericardium", "view": "tte_a4c", "source": "ASE/EACVI Diastolic Function 2016", "inputs": [{"k": "expE", "l": "Expiratory mitral E", "u": "m/s", "d": 0.9, "lo": 0.1, "hi": 2.5}, {"k": "inspE", "l": "Inspiratory mitral E", "u": "m/s", "d": 0.6, "lo": 0.1, "hi": 2.5}], "out": {"l": "Respiratory variation", "u": "%"}, "example": {"expE": 0.9, "inspE": 0.6}, "how": "Fall in mitral E of 25 percent or more on inspiration supports constriction or tamponade physiology by context.", "limits": "Positive pressure ventilation reverses the patterns. Free breathing only.", "fig": "a4c"}, {"id": "tricuspid-respiratory", "name": "Tricuspid inflow respiratory variation", "cat": "Pericardium", "view": "tte_a4c_rv_focus", "source": "ASE/EACVI Diastolic Function 2016", "inputs": [{"k": "expE", "l": "Expiratory tricuspid E", "u": "m/s", "d": 0.5, "lo": 0.05, "hi": 2.0}, {"k": "inspE", "l": "Inspiratory tricuspid E", "u": "m/s", "d": 0.75, "lo": 0.05, "hi": 2.5}], "out": {"l": "Respiratory variation", "u": "%"}, "example": {"expE": 0.5, "inspE": 0.75}, "how": "Rise in tricuspid E of 40 percent or more on inspiration supports constriction or tamponade physiology by context.", "limits": "Positive pressure ventilation reverses the patterns. Free breathing only.", "fig": "a4c"}, {"id": "lvot-respiratory", "name": "LVOT VTI respiratory variation", "cat": "Pericardium", "view": "tte_a5c", "source": "ASE/EACVI Diastolic Function 2016", "inputs": [{"k": "expV", "l": "Expiratory LVOT VTI", "u": "cm", "d": 22, "lo": 3, "hi": 60}, {"k": "inspV", "l": "Inspiratory LVOT VTI", "u": "cm", "d": 19, "lo": 3, "hi": 60}], "out": {"l": "Respiratory variation", "u": "%"}, "example": {"expV": 22, "inspV": 19}, "how": "Pulsus paradoxus physiology shows inspiratory fall in LVOT VTI. Record with a respirometer trace where possible.", "limits": "Positive pressure ventilation reverses the patterns. Free breathing only.", "fig": "a4c"}, {"id": "doppler-equation", "name": "Doppler equation", "cat": "Physics", "view": "tte_a4c", "source": "Ultrasound physics (ASE physics reviews)", "inputs": [{"k": "f0", "l": "Transmit frequency", "u": "MHz", "d": 3.0, "lo": 0.5, "hi": 12}, {"k": "v", "l": "Blood velocity", "u": "m/s", "d": 1.5, "lo": 0.05, "hi": 7.0}, {"k": "theta", "l": "Angle theta", "u": "degrees", "d": 20, "lo": 0, "hi": 85}, {"k": "c", "l": "Speed of sound", "u": "m/s", "d": 1540, "lo": 1400, "hi": 1650}], "out": {"l": "Doppler shift", "u": "kHz"}, "example": {"f0": 3.0, "v": 1.5, "theta": 20, "c": 1540}, "how": "Shift equals 2 f0 v cos theta over c. Cos theta is why angle control matters.", "limits": "Assumes soft tissue speed. Fat and muscle differ slightly.", "fig": "physics"}, {"id": "bernoulli", "name": "Bernoulli gradient (simplified and extended)", "cat": "Physics", "view": "tte_a5c", "source": "Ultrasound physics (ASE physics reviews)", "inputs": [{"k": "v2", "l": "Distal velocity", "u": "m/s", "d": 4.0, "lo": 0.1, "hi": 8.0}, {"k": "v1", "l": "Proximal velocity", "u": "m/s", "d": 1.0, "lo": 0.05, "hi": 4.0}], "out": {"l": "Peak gradient", "u": "mmHg"}, "example": {"v2": 4.0, "v1": 1.0}, "how": "Simplified: 4 v2 squared. Extended subtracts 4 v1 squared when proximal velocity exceeds about 1.5 m/s.", "limits": "Ignores viscosity and acceleration. Long tunnels and serial stenoses break it.", "fig": "physics"}, {"id": "poiseuille", "name": "Poiseuille flow", "cat": "Physics", "view": "tte_a4c", "source": "Ultrasound physics (ASE physics reviews)", "inputs": [{"k": "dp", "l": "Pressure difference", "u": "mmHg", "d": 10, "lo": 0.1, "hi": 100}, {"k": "r", "l": "Radius", "u": "mm", "d": 2.0, "lo": 0.1, "hi": 20}, {"k": "eta", "l": "Viscosity (water 1)", "u": "relative", "d": 3.5, "lo": 0.5, "hi": 10}, {"k": "len", "l": "Length", "u": "cm", "d": 5, "lo": 0.1, "hi": 50}], "out": {"l": "Relative flow (radius to the fourth)", "u": "index"}, "example": {"dp": 10, "r": 2.0, "eta": 3.5, "len": 5}, "how": "Flow rises with radius to the fourth power. Halving radius cuts flow sixteen fold at the same pressure.", "limits": "Blood is non Newtonian and vessels are distensible. A teaching model.", "fig": "physics"}, {"id": "pulse-repetition", "name": "PRF and Nyquist limit", "cat": "Physics", "view": "tte_a4c", "source": "Ultrasound physics (ASE physics reviews)", "inputs": [{"k": "depth", "l": "Depth", "u": "cm", "d": 16, "lo": 2, "hi": 30}, {"k": "f0", "l": "Transmit frequency", "u": "MHz", "d": 3.0, "lo": 0.5, "hi": 12}, {"k": "theta", "l": "Angle theta", "u": "degrees", "d": 0, "lo": 0, "hi": 85}], "out": {"l": "Nyquist velocity", "u": "m/s"}, "example": {"depth": 16, "f0": 3.0, "theta": 0}, "how": "Max PRF equals c over twice depth. Nyquist is half the PRF, converted to velocity by the Doppler equation.", "limits": "Baseline shift and lower frequency raise the usable limit.", "fig": "physics"}, {"id": "pulse-geometry", "name": "Pulse geometry: axial and lateral resolution", "cat": "Physics", "view": "tte_a4c", "source": "Ultrasound physics (ASE physics reviews)", "inputs": [{"k": "f0", "l": "Frequency", "u": "MHz", "d": 3.5, "lo": 0.5, "hi": 15}, {"k": "cycles", "l": "Cycles per pulse", "u": "count", "d": 3, "lo": 1, "hi": 8}, {"k": "aperture", "l": "Aperture", "u": "mm", "d": 20, "lo": 2, "hi": 60}, {"k": "depth", "l": "Depth", "u": "mm", "d": 120, "lo": 10, "hi": 300}], "out": {"l": "Axial resolution", "u": "mm"}, "example": {"f0": 3.5, "cycles": 3, "aperture": 20, "depth": 120}, "how": "Axial resolution is half the spatial pulse length. Lateral resolution widens with depth over aperture.", "limits": "Focus position dominates real lateral resolution.", "fig": "physics"}, {"id": "acoustic", "name": "Acoustics: wavelength, impedance, reflection", "cat": "Physics", "view": "tte_a4c", "source": "Ultrasound physics (ASE physics reviews)", "inputs": [{"k": "f0", "l": "Frequency", "u": "MHz", "d": 3.0, "lo": 0.5, "hi": 15}, {"k": "z1", "l": "Impedance tissue 1", "u": "MRayl", "d": 1.65, "lo": 0.1, "hi": 10}, {"k": "z2", "l": "Impedance tissue 2", "u": "MRayl", "d": 1.45, "lo": 0.1, "hi": 10}], "out": {"l": "Wavelength", "u": "mm"}, "example": {"f0": 3.0, "z1": 1.65, "z2": 1.45}, "how": "Wavelength equals 1540 over frequency. Reflection coefficient comes from the impedance mismatch squared.", "limits": "Normal incidence only. Angle spreads the reflected beam.", "fig": "physics"}, {"id": "wave-relations", "name": "Wave relations: period, frequency, speed", "cat": "Physics", "view": "tte_a4c", "source": "Ultrasound physics (ASE physics reviews)", "inputs": [{"k": "f0", "l": "Frequency", "u": "MHz", "d": 2.5, "lo": 0.1, "hi": 20}, {"k": "c", "l": "Speed of sound", "u": "m/s", "d": 1540, "lo": 300, "hi": 6000}], "out": {"l": "Period", "u": "µs"}, "example": {"f0": 2.5, "c": 1540}, "how": "Period is 1 over frequency; wavelength is speed over frequency; speed is fixed by the medium, not the probe.", "limits": "In soft tissue use 1540 m/s unless the medium is stated.", "fig": "physics"}, {"id": "pathway-diastology", "name": "Integrated diastology pathway", "cat": "Pathways", "view": "tte_a4c", "source": "ASE/EACVI Diastolic Function 2016", "inputs": [{"k": "e", "l": "Mitral E", "u": "m/s", "d": 0.95, "lo": 0.1, "hi": 2.5}, {"k": "a", "l": "Mitral A", "u": "m/s", "d": 0.6, "lo": 0.05, "hi": 2.5}, {"k": "sept", "l": "Septal e prime", "u": "cm/s", "d": 6.5, "lo": 1, "hi": 25}, {"k": "lat", "l": "Lateral e prime", "u": "cm/s", "d": 8, "lo": 1, "hi": 25}, {"k": "lavi", "l": "LA volume index", "u": "mL/m²", "d": 36, "lo": 5, "hi": 120}, {"k": "trv", "l": "TR velocity", "u": "m/s", "d": 2.7, "lo": 0.5, "hi": 5.0}], "out": {"l": "Average E/e prime", "u": "ratio"}, "example": {"e": 0.95, "a": 0.6, "sept": 6.5, "lat": 8, "lavi": 36, "trv": 2.7}, "how": "Combines the four ASE/EACVI 2016 variables into one verdict with the vote shown, then grades dysfunction by E/A and deceleration pattern.", "limits": "Use the dedicated pathway in AF, MAC, HCM or a prosthesis.", "fig": "generic"}, {"id": "pathway-as", "name": "Integrated aortic stenosis pathway", "cat": "Pathways", "view": "tte_a5c", "source": "ESC/EACTS Valvular Heart Disease 2021", "inputs": [{"k": "peakv", "l": "Peak velocity", "u": "m/s", "d": 4.3, "lo": 0.5, "hi": 7.0}, {"k": "meanG", "l": "Mean gradient", "u": "mmHg", "d": 44, "lo": 1, "hi": 120}, {"k": "ava", "l": "AVA by continuity", "u": "cm²", "d": 0.85, "lo": 0.2, "hi": 3.5}, {"k": "svi", "l": "Stroke volume index", "u": "mL/m²", "d": 32, "lo": 10, "hi": 80}, {"k": "lvef", "l": "LVEF", "u": "%", "d": 48, "lo": 5, "hi": 85}], "out": {"l": "Mean gradient", "u": "mmHg"}, "example": {"peakv": 4.3, "meanG": 44, "ava": 0.85, "svi": 32, "lvef": 48}, "how": "High gradient severe, or low flow low gradient split by flow and EF, with dobutamine or calcium score as the next step named.", "limits": "True severe vs pseudo severe needs a flow challenge in classical low flow.", "fig": "a5c"}, {"id": "pathway-mr", "name": "Integrated mitral regurgitation pathway", "cat": "Pathways", "view": "tte_a4c", "source": "ASE Native Valve Regurgitation 2017", "inputs": [{"k": "eroa", "l": "EROA", "u": "cm²", "d": 0.42, "lo": 0.02, "hi": 1.5}, {"k": "rvol", "l": "Regurgitant volume", "u": "mL", "d": 62, "lo": 1, "hi": 200}, {"k": "vc", "l": "Vena contracta", "u": "mm", "d": 7, "lo": 1, "hi": 20}, {"k": "lavi", "l": "LA volume index", "u": "mL/m²", "d": 44, "lo": 5, "hi": 120}], "out": {"l": "EROA", "u": "cm²"}, "example": {"eroa": 0.42, "rvol": 62, "vc": 7, "lavi": 44}, "how": "Primary MR grades at EROA 0.40 and volume 60; secondary MR at lower cut offs. Mechanism decides the pathway.", "limits": "State primary or secondary in the report; cut offs differ.", "fig": "generic"}];
